exercises.solution:
def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def first_repeat(text):
    seen = ""
    for char in text:
        if char in seen:
            break
        seen += char
    else:
        return None
    return char
